import{_ as d,a as r,c as e,ac as a}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"易经：术语、读音与常见误解","description":"按文本层次、卦爻结构、占辞、图学和后世术数整理常见术语，补充难读卦名与经传名句出处。","frontmatter":{"title":"易经：术语、读音与常见误解","description":"按文本层次、卦爻结构、占辞、图学和后世术数整理常见术语，补充难读卦名与经传名句出处。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"按文本层次、卦爻结构、占辞、图学和后世术数整理常见术语，补充难读卦名与经传名句出处。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"把《周易》读进具体问题：乾坤、泰否、既济未济对读","link":"/life/personal/yijing/reading-practice"},"next":{"text":"易经：古籍书目、图源与整理说明","link":"/life/personal/yijing/bibliography"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"把《周易》读进具体问题：乾坤、泰否、既济未济对读","link":"/life/personal/yijing/reading-practice"},"next":{"text":"易经：古籍书目、图源与整理说明","link":"/life/personal/yijing/bibliography"}},"headers":[],"relativePath":"life/personal/yijing/glossary.md","filePath":"life/personal/yijing/glossary.md"}'),i={name:"life/personal/yijing/glossary.md"};function n(l,t,o,h,s,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="易经-术语、读音与常见误解" tabindex="-1">易经：术语、读音与常见误解 <a class="header-anchor" href="#易经-术语、读音与常见误解" aria-label="Permalink to &quot;易经：术语、读音与常见误解&quot;">​</a></h1><p>本表用于阅读本专题时快速回查。释义以常见经传解释为主；有历史分歧的词保留说明，不把简短释义当成所有时代的唯一答案。遇到具体爻辞，仍应返回上下文和古注。</p><h2 id="文本层次" tabindex="-1">文本层次 <a class="header-anchor" href="#文本层次" aria-label="Permalink to &quot;文本层次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词</th><th>入门解释</th><th>容易混淆的地方</th></tr></thead><tbody><tr><td>易</td><td>变化及相关经典传统的名称</td><td>“易”的古义、三义等说法须落实到具体注家</td></tr><tr><td>周易</td><td>传世易书的名称</td><td>日常有时泛指经传合编，有时特指经文</td></tr><tr><td>经</td><td>六十四卦卦爻辞的核心文本</td><td>不等于所有装订在同一本书里的文字</td></tr><tr><td>传</td><td>解释、发挥经文的篇章</td><td>“传”在这里不是人物传记</td></tr><tr><td>十翼</td><td>彖上下、象上下、系辞上下、文言、说卦、序卦、杂卦</td><td>七种十篇；大象小象不是象上下的对应分卷</td></tr><tr><td>卦辞</td><td>一卦开头的经文辞句</td><td>古注有时称它为彖辞，需与彖传区分</td></tr><tr><td>爻辞</td><td>附于各爻的经文辞句</td><td>与对应的小象属于不同层次</td></tr><tr><td>大象</td><td>由整卦之象引申为行动、修养的传文</td><td>不是“大一些的卦图”</td></tr><tr><td>小象</td><td>对各爻辞作解释的传文</td><td>同一卦的大象与小象可以一起归入象传</td></tr><tr><td>注、疏</td><td>注释经文；疏进一步解释经与注</td><td>《周易正义》中的经、注、疏需要分别辨认</td></tr><tr><td>本义</td><td>朱熹书名中的“本义”，也可泛称本来意义</td><td>书名不是作者解释必为最终原义的证明</td></tr><tr><td>义理、象数</td><td>重视意义伦理或符号数位的解释取向</td><td>两者常交错，不是互不相干的两部《易经》</td></tr></tbody></table><p>文本层次可核对<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3" target="_blank" rel="noopener noreferrer">《易传》目录</a>及<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《周易本义》四库本提要</a>。</p><h2 id="卦爻结构" tabindex="-1">卦爻结构 <a class="header-anchor" href="#卦爻结构" aria-label="Permalink to &quot;卦爻结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词</th><th>释义</th></tr></thead><tbody><tr><td>爻（yáo）</td><td>卦的一画；阴画虽分两段，仍是一爻</td></tr><tr><td>经卦、三画卦</td><td>乾兑离震巽坎艮坤八种三爻组合</td></tr><tr><td>别卦、重卦</td><td>两个三画卦组成的六爻卦</td></tr><tr><td>内卦、下卦</td><td>六画卦最下面的三爻</td></tr><tr><td>外卦、上卦</td><td>六画卦最上面的三爻</td></tr><tr><td>初、上</td><td>第一爻与第六爻的位置名称</td></tr><tr><td>九、六</td><td>阳爻与阴爻在爻题中的名称</td></tr><tr><td>用九、用六</td><td>乾坤六爻之后的特殊条文，不是第七爻</td></tr><tr><td>卦德</td><td>对卦的性质、功能的概括，如健、顺、动、入</td></tr><tr><td>时</td><td>全卦所面对的情势及其发展阶段，不只指日历时间</td></tr><tr><td>位</td><td>爻在六位中的位置以及由此讨论的处境</td></tr><tr><td>得中</td><td>处二或五，即内卦或外卦的中位</td></tr><tr><td>当位、得正</td><td>常见规则为阳居奇数位、阴居偶数位；不是自动吉凶判定</td></tr><tr><td>中正</td><td>得中而又得正；仍须看具体卦义</td></tr><tr><td>应</td><td>常指初四、二五、三上之间的对应关系</td></tr><tr><td>比（bǐ）</td><td>相近相邻的关系；作卦名时也读 bǐ</td></tr><tr><td>承、乘</td><td>下承上、上乘下的相邻关系；古注会赋予具体意义</td></tr><tr><td>卦主</td><td>某些解释中足以统摄整卦意义的关键爻；各家取法可能不同</td></tr><tr><td>本卦、之卦</td><td>起得的卦与指定爻改变后形成的卦</td></tr><tr><td>动爻、变爻</td><td>一次筮占中需要变化的爻；不是所有爻题为九六者都同时动</td></tr><tr><td>错卦</td><td>今人常指六爻全部阴阳相反的卦</td></tr><tr><td>综卦、覆卦</td><td>今人常指整个卦上下倒转后的卦</td></tr><tr><td>互体、互卦</td><td>由中间爻组建三画卦或重卦的解释方法</td></tr><tr><td>消息</td><td>在易学中常讲消退与滋长，不是“通知内容”</td></tr></tbody></table><p>上述结构术语的例子见<a href="./symbols">卦画入门</a>；卦主与整体阅读可参看王弼<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E7%95%A5%E4%BE%8B/%E6%98%8E%E5%BD%96" target="_blank" rel="noopener noreferrer">《明彖》</a>。</p><h2 id="占辞中的常见用语" tabindex="-1">占辞中的常见用语 <a class="header-anchor" href="#占辞中的常见用语" aria-label="Permalink to &quot;占辞中的常见用语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词句</th><th>阅读提示</th></tr></thead><tbody><tr><td>元</td><td>大、始等解释须随句；“元亨利贞”在《文言》中另有四德阐释</td></tr><tr><td>亨</td><td>通达、亨通是常见传注解释；与祭享语言的关系属于训诂问题</td></tr><tr><td>利</td><td>有利于某一行动或状态，后面经常有具体对象</td></tr><tr><td>贞（貞）</td><td>经传解释常作正、固守正道；早期占问语境及其语义演变不能省略</td></tr><tr><td>吉、凶</td><td>传统占断或评价词，常附着于具体条件，不是现实结果的实验概率</td></tr><tr><td>悔</td><td>过后产生的悔恨或应悔之处，要与“悔亡”等连读</td></tr><tr><td>吝</td><td>困窘、羞吝或遗憾等，具体译法须看句子</td></tr><tr><td>厉（厲）</td><td>危险、危惧的状态，不能简单当成“厉害”</td></tr><tr><td>无咎</td><td>无过咎；有时涉及补救得当，不等于获得最大利益</td></tr><tr><td>悔亡</td><td>悔恨消除或不再构成问题，仍有条件</td></tr><tr><td>有孚</td><td>常与诚信、可信相连；具体古义有不同讨论，不宜一律现代化</td></tr><tr><td>利见大人</td><td>有利于见有德有位者，是常见解释；不是“遇到富人就会发财”</td></tr><tr><td>利涉大川</td><td>涉大河的行动语境，古注也作承担重大艰难事务的引申</td></tr><tr><td>有攸往</td><td>有所前往、有所作为；“攸”是“所”的一类用法</td></tr><tr><td>勿用、勿逐</td><td>不要采取相应行动，不能漏掉否定词</td></tr><tr><td>无、無</td><td>古籍中常见异体或不同书写习惯，本站引文保留来源用字</td></tr></tbody></table><p><a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E7%B9%AB%E8%BE%AD%E4%B8%8A" target="_blank" rel="noopener noreferrer">《系辞上》第二、三章</a>专门说明吉凶、悔吝、无咎等概念。表中是阅读提示，不是逐字词典；像“贞”“孚”这样的字，在经文、传文与现代古文字研究中可能有不同解释。</p><h2 id="容易读错的卦名与篇名" tabindex="-1">容易读错的卦名与篇名 <a class="header-anchor" href="#容易读错的卦名与篇名" aria-label="Permalink to &quot;容易读错的卦名与篇名&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>常用读音</th><th>提醒</th></tr></thead><tbody><tr><td>乾</td><td>qián</td><td>乾卦不读 gān</td></tr><tr><td>屯</td><td>zhūn</td><td>卦名读 zhūn，与屯驻的 tún 区分</td></tr><tr><td>小畜、大畜</td><td>xiǎo xù、dà xù</td><td>畜有蓄聚、畜养等义，不能一概只译储蓄</td></tr><tr><td>否</td><td>pǐ</td><td>闭塞义，不读表示否定的 fǒu</td></tr><tr><td>蛊</td><td>gǔ</td><td>本卦涉及弊坏及整治，不能仅按现代怪谈理解</td></tr><tr><td>噬嗑</td><td>shì hé</td><td>咬合、噬而合之</td></tr><tr><td>贲</td><td>bì</td><td>卦名常读 bì，涉及文饰</td></tr><tr><td>颐</td><td>yí</td><td>颐养、口颊之象</td></tr><tr><td>遯</td><td>dùn</td><td>通常也写“遁”，指退避</td></tr><tr><td>睽</td><td>kuí</td><td>相乖、差异</td></tr><tr><td>蹇</td><td>jiǎn</td><td>行进艰难</td></tr><tr><td>解</td><td>xiè</td><td>卦名取解除、解散之义的常用读法</td></tr><tr><td>夬</td><td>guài</td><td>决；与现代“怪”不是同一个词</td></tr><tr><td>姤</td><td>gòu</td><td>遇，相遇</td></tr><tr><td>艮</td><td>gèn</td><td>止，山象</td></tr><tr><td>巽</td><td>xùn</td><td>入，风木之象</td></tr><tr><td>彖</td><td>tuàn</td><td>彖辞、彖传</td></tr><tr><td>系辞</td><td>xì cí</td><td>系于经文的解释、相关论述</td></tr><tr><td>蓍</td><td>shī</td><td>传统筮法所用植物名</td></tr><tr><td>筮</td><td>shì</td><td>用蓍等进行占筮</td></tr></tbody></table><p>这是现代普通话阅读辅助，不是对先秦古音的复原。不同古注的音义材料应另行核对。</p><h2 id="经常被错安出处的名句" tabindex="-1">经常被错安出处的名句 <a class="header-anchor" href="#经常被错安出处的名句" aria-label="Permalink to &quot;经常被错安出处的名句&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名句</th><th>所在层次</th><th>核对入口</th></tr></thead><tbody><tr><td>潜龙勿用</td><td>乾初九爻辞</td><td><a href="./hexagrams-01-08#gua-01">乾</a></td></tr><tr><td>亢龙有悔</td><td>乾上九爻辞</td><td><a href="./hexagrams-01-08#gua-01">乾</a></td></tr><tr><td>天行健，君子以自强不息</td><td>乾大象</td><td><a href="./hexagrams-01-08#gua-01">乾</a></td></tr><tr><td>地势坤，君子以厚德载物</td><td>坤大象</td><td><a href="./hexagrams-01-08#gua-02">坤</a></td></tr><tr><td>一阴一阳之谓道</td><td>系辞上</td><td><a href="./ten-wings">十翼</a></td></tr><tr><td>生生之谓易</td><td>系辞上</td><td><a href="./philosophy">思想专题</a></td></tr><tr><td>穷则变，变则通，通则久</td><td>系辞下</td><td><a href="./philosophy">思想专题</a></td></tr><tr><td>君子以思患而豫防之</td><td>既济大象</td><td><a href="./hexagrams-57-64#gua-63">既济</a></td></tr></tbody></table><h2 id="五个需要马上纠正的误解" tabindex="-1">五个需要马上纠正的误解 <a class="header-anchor" href="#五个需要马上纠正的误解" aria-label="Permalink to &quot;五个需要马上纠正的误解&quot;">​</a></h2><ol><li><strong>“阴就是坏，阳就是好。”</strong> 阴阳是成卦和解释变化的基本关系，不能直接等同善恶。</li><li><strong>“每个卦固定代表一种职业、疾病或性格。”</strong> 原文和注家的解释远比单一标签丰富。</li><li><strong>“九五永远是好位。”</strong> 位是条件之一，仍须读该卦九五实际写了什么。</li><li><strong>“阴阳鱼图就是最早的易经。”</strong> 太极观念、后世太极图和不同黑白图案不能不分时代地合并。</li><li><strong>“所有易学都是《周易》原文。”</strong> 后世体系有自己的书、规则和术语，见<a href="./traditions">流变与术数</a>。</li></ol><p><a href="./overview">返回专题</a> · <a href="./bibliography">古籍书目</a></p>',19)])])}const c=d(i,[["render",n]]);export{b as __pageData,c as default};
